/**
 * Finnomena brand CSS custom properties — for projects that want
 * Finnomena's colors/typography/spacing WITHOUT installing
 * @coinbase/cds-web or using CDS React components.
 *
 * COLORS come from Core's Theme (ADR 0009). Each --color-* role takes the
 * Core Theme token that
 * ${CLAUDE_PLUGIN_ROOT}/theme/css/core-roles.json names for it, in
 * light and in dark, and the maintainers' Core sync writes the value from
 * the Core snapshot
 * (${CLAUDE_PLUGIN_ROOT}/core/theme.json). Do not edit a color here:
 * the repository check refuses one that differs from the snapshot. A role
 * the table gives no token (it says why) keeps its earlier value and is
 * PROVISIONAL: fgPrimary, bgPrimaryWash, bgSecondaryWash, bgLineHeavy,
 * bgLinePrimarySubtle and the subtle accents.
 *
 * TYPE SIZES AND LINE HEIGHTS come from Core's text styles (ADR 0009).
 * Each type role takes the Core text style that
 * ${CLAUDE_PLUGIN_ROOT}/theme/css/core-type-roles.json names for it, and
 * the Core sync writes its --fontSize-* and --lineHeight-* from the Core
 * snapshot (${CLAUDE_PLUGIN_ROOT}/core/text-styles.json), in px. From
 * title1 down the line heights follow Core's Thai rule, 1.4 times the
 * size rounded up to a multiple of 4 (Core's ADR 0012, Thai line
 * heights, worked out for Finnomena Trek); display1 to display3 take
 * Core's Display styles, which are tighter.
 * Do not edit one here: the repository check refuses a value that
 * differs from the snapshot.
 *
 * EVERYTHING ELSE (font family and weight, space, radius) is
 * hand-captured, not generated: the byte-exact output of
 * @coinbase/cds-web@9.26.1's own `createThemeCssVars()` against
 * `createNeonTheme()`. Recapture it by hand when
 * ${CLAUDE_PLUGIN_ROOT}/theme/cds/theme.config.ts's `neonTheme` changes.
 *
 * NAMES match what CDS's ThemeProvider emits at runtime
 * (`--{category}-{key}`, e.g. `--color-fg`, `--space-2`,
 * `--borderRadius-200`, `--fontFamily-body`), so an app already on CDS
 * keeps its `var(--color-fg)` references. The colors, type sizes and line
 * heights are no longer CDS's: the frozen CDS theme
 * (${CLAUDE_PLUGIN_ROOT}/theme/cds/) keeps the values it had, and this
 * file follows Core.
 *
 * SCOPE: only color, typography (fontFamily/fontSize/fontWeight/
 * lineHeight), space, and borderRadius are included — the fields Finnomena
 * actually has brand data for. Raw spectrum primitives (--blue60 etc.),
 * illustration colors, and fields with no Finnomena data at all (iconSize,
 * avatarSize, controlSize, borderWidth, textTransform, shadow,
 * fontFamilyMono) are deliberately omitted — app code should reference
 * semantic tokens (--color-fg, not a raw spectrum step), and CDS's generic
 * Coinbase defaults for untouched fields don't belong in a "Finnomena"
 * branded file. The one exception to the CDS capture is the provisional
 * --layout-* group, copied by hand from the breakpoint token export (see
 * its own comment below); CDS's ThemeProvider never emits it.
 *
 * DARK MODE: applies automatically via `prefers-color-scheme: dark`, with
 * a `[data-theme="dark"]` attribute as a manual override (put
 * `data-theme="dark"` on <html> to force dark regardless of OS setting, or
 * `data-theme="light"` to force light). Swap this convention for your
 * project's own dark-mode mechanism (a `.dark` class, etc.) if it already
 * has one — this is a default assumption, not verified against any
 * specific target project.
 *
 * USAGE: copy this file into your project (e.g. src/theme/theme.css) and
 * import it once (e.g. in your root CSS or main entry file):
 *   import "./theme/theme.css";
 * Then reference values as var(--color-fg), var(--space-2), etc.
 *
 * TIERS:
 *   - Colors only: use only the --color-* variables below.
 *   - Colors + typography: also use --fontFamily-*, --fontSize-*,
 *     --fontWeight-*, --lineHeight-*, --space-*, --borderRadius-*.
 *     Immersive pages also take their content column from --layout-*.
 *   - Full CDS: don't use this file — see
 *     ${CLAUDE_PLUGIN_ROOT}/skills/neon-create instead (ThemeProvider +
 *     createNeonTheme() + real CDS components).
 */

:root {
  /* --- Colors (light — default) --- */
  --color-currentColor: currentColor;
  --color-transparent: rgba(255, 255, 255, 0);

  --color-fg: rgba(0, 0, 0, 0.851);
  --color-fgMuted: rgba(0, 0, 0, 0.651);
  --color-fgInverse: rgb(255, 255, 255);
  --color-fgPrimary: rgb(1, 23, 43);
  --color-fgWarning: rgb(211, 84, 12);
  --color-fgPositive: rgb(0, 116, 53);
  --color-fgNegative: rgb(157, 6, 6);

  --color-bg: rgb(255, 255, 255);
  --color-bgAlternate: rgb(242, 242, 242);
  --color-bgInverse: rgb(0, 0, 0);
  --color-bgOverlay: rgba(0, 0, 0, 0.2);
  --color-bgElevation1: rgb(255, 255, 255);
  --color-bgElevation2: rgb(242, 243, 244);
  --color-bgPrimary: rgb(1, 23, 43);
  --color-bgPrimaryWash: rgb(242, 243, 244);
  --color-bgSecondary: rgb(242, 242, 242);
  --color-bgTertiary: rgb(255, 255, 255);
  --color-bgSecondaryWash: rgb(247, 248, 249);
  --color-bgNegative: rgb(214, 8, 8);
  --color-bgNegativeWash: rgb(255, 245, 245);
  --color-bgPositive: rgb(0, 150, 70);
  --color-bgPositiveWash: rgb(230, 253, 240);
  --color-bgWarning: rgb(211, 84, 12);
  --color-bgWarningWash: rgb(254, 247, 243);

  --color-bgLine: rgba(0, 0, 0, 0.122);
  --color-bgLineHeavy: rgba(91, 97, 110, 0.66);
  --color-bgLineInverse: rgb(255, 255, 255);
  --color-bgLinePrimary: rgb(105, 104, 239);
  --color-bgLinePrimarySubtle: rgb(115, 162, 255);

  --color-accentSubtleRed: rgb(255, 245, 245);
  --color-accentBoldRed: rgb(247, 50, 50);
  --color-accentSubtleGreen: rgb(230, 253, 240);
  --color-accentBoldGreen: rgb(0, 231, 107);
  --color-accentSubtleBlue: rgb(246, 253, 255);
  --color-accentBoldBlue: rgb(80, 207, 255);
  --color-accentSubtlePurple: rgb(251, 246, 252);
  --color-accentBoldPurple: rgb(170, 70, 195);
  --color-accentSubtleYellow: rgb(254, 255, 245);
  --color-accentBoldYellow: rgb(242, 249, 60);
  --color-accentSubtleGray: rgb(242, 243, 244);
  --color-accentBoldGray: rgb(1, 23, 43);

  /* Component-scoped Core tokens, each entered by the item that uses it:
   * Button's label and fill tokens, and Link's ink for the link button. */
  --color-fgOnColor: rgb(255, 255, 255);
  --color-fgOnBrand: rgba(0, 0, 0, 0.851);
  --color-fgDisabled: rgba(0, 0, 0, 0.451);
  --color-fgInverseDisabled: rgba(255, 255, 255, 0.451);
  --color-fgLink: rgb(24, 23, 231);
  --color-fgLinkHover: rgb(20, 20, 196);

  --color-bgButtonPrimaryHover: rgb(26, 46, 64);
  --color-bgButtonPrimaryActive: rgb(52, 69, 85);
  --color-bgButtonSecondary: rgba(1, 23, 43, 0.102);
  --color-bgButtonSecondaryHover: rgba(1, 23, 43, 0.122);
  --color-bgButtonSecondaryActive: rgba(1, 23, 43, 0.149);
  --color-bgButtonDangerHover: rgb(186, 7, 7);
  --color-bgButtonDangerActive: rgb(157, 6, 6);
  --color-bgButtonBrand: rgb(242, 249, 60);
  --color-bgButtonBrandHover: rgb(244, 250, 89);
  --color-bgButtonBrandActive: rgb(245, 251, 109);
  --color-bgButtonInverse: rgb(255, 255, 255);
  --color-bgButtonInverseHover: rgb(230, 230, 230);
  --color-bgButtonInverseActive: rgb(217, 217, 217);
  --color-bgButtonInverseDisabled: rgba(255, 255, 255, 0.102);
  --color-bgButtonDisabled: rgba(1, 23, 43, 0.102);

  /* --- Typography (mode-independent) --- */
  --fontFamily-display1: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-display2: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-display3: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title1: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title2: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title3: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title4: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-headline: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-body: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-label1: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-label2: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-caption: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-legal: 'IBM Plex Sans Thai', sans-serif;

  --fontSize-display1: 92px;
  --fontSize-display2: 60px;
  --fontSize-display3: 54px;
  --fontSize-title1: 28px;
  --fontSize-title2: 22px;
  --fontSize-title3: 20px;
  --fontSize-title4: 20px;
  --fontSize-headline: 17px;
  --fontSize-body: 17px;
  --fontSize-label1: 15px;
  --fontSize-label2: 15px;
  --fontSize-caption: 13px;
  --fontSize-legal: 13px;

  --fontWeight-display1: 400;
  --fontWeight-display2: 400;
  --fontWeight-display3: 700;
  --fontWeight-title1: 400;
  --fontWeight-title2: 400;
  --fontWeight-title3: 400;
  --fontWeight-title4: 400;
  --fontWeight-headline: 500;
  --fontWeight-body: 400;
  --fontWeight-label1: 600;
  --fontWeight-label2: 400;
  --fontWeight-caption: 600;
  --fontWeight-legal: 400;

  --lineHeight-display1: 102px;
  --lineHeight-display2: 70px;
  --lineHeight-display3: 64px;
  --lineHeight-title1: 40px;
  --lineHeight-title2: 32px;
  --lineHeight-title3: 28px;
  --lineHeight-title4: 28px;
  --lineHeight-headline: 24px;
  --lineHeight-body: 24px;
  --lineHeight-label1: 24px;
  --lineHeight-label2: 24px;
  --lineHeight-caption: 20px;
  --lineHeight-legal: 20px;

  /* --- Spacing (mode-independent) --- */
  --space-0: 0px;
  --space-0_25: 2px;
  --space-0_5: 4px;
  --space-0_75: 6px;
  --space-1: 8px;
  --space-1_5: 12px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 32px;
  --space-5: 40px;
  --space-6: 48px;
  --space-7: 56px;
  --space-8: 64px;
  --space-9: 72px;
  --space-10: 80px;

  /* --- Border radius (mode-independent) --- */
  --borderRadius-0: 0px;
  --borderRadius-100: 4px;
  --borderRadius-200: 8px;
  --borderRadius-300: 12px;
  --borderRadius-400: 16px;
  --borderRadius-500: 24px;
  --borderRadius-600: 32px;
  --borderRadius-700: 40px;
  --borderRadius-800: 48px;
  --borderRadius-900: 56px;
  --borderRadius-1000: 100000px;

  /* --- Layout (mode-independent) ---
   * PROVISIONAL: the Immersive pages' shared content column, copied by hand
   * from ${CLAUDE_PLUGIN_ROOT}/theme/tokens/breakpoint.json's Immersive
   * Layout ("Content View max-width" from xxxl_1440px; "End margins" from
   * sm_320px). Not a CDS field and nothing regenerates it. The end margin
   * widens below. */
  --layout-contentMaxWidth: 1440px;
  --layout-endMargin: 16px;
}

/* "End margins" from the xxxl_1440px tier (Viewport min-width 1440). */
@media (min-width: 1440px) {
  :root {
    --layout-endMargin: 24px;
  }
}

/* --- Colors (dark) — OS preference --- */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --color-fg: rgb(255, 255, 255);
    --color-fgMuted: rgba(255, 255, 255, 0.651);
    --color-fgInverse: rgba(0, 0, 0, 0.851);
    --color-fgPrimary: rgb(230, 232, 234);
    --color-fgWarning: rgb(242, 100, 20);
    --color-fgNegative: rgb(251, 153, 153);
    --color-fgPositive: rgb(0, 196, 91);

    --color-bg: rgb(0, 0, 0);
    --color-bgAlternate: rgb(26, 26, 26);
    --color-bgInverse: rgb(255, 255, 255);
    --color-bgOverlay: rgba(0, 0, 0, 0.502);
    --color-bgElevation1: rgb(26, 26, 26);
    --color-bgElevation2: rgb(38, 38, 38);
    --color-bgPrimary: rgb(65, 81, 96);
    --color-bgPrimaryWash: rgb(1, 23, 43);
    --color-bgSecondary: rgb(26, 26, 26);
    --color-bgTertiary: rgb(51, 51, 51);
    --color-bgSecondaryWash: rgb(20, 21, 25);
    --color-bgNegative: rgb(214, 8, 8);
    --color-bgNegativeWash: rgba(247, 50, 50, 0.149);
    --color-bgPositive: rgb(0, 196, 91);
    --color-bgPositiveWash: rgba(0, 231, 107, 0.149);
    --color-bgWarning: rgb(242, 100, 20);
    --color-bgWarningWash: rgba(242, 100, 20, 0.149);

    --color-bgLine: rgba(255, 255, 255, 0.18);
    --color-bgLineHeavy: rgba(138, 145, 158, 0.66);
    --color-bgLineInverse: rgb(0, 0, 0);
    --color-bgLinePrimary: rgb(128, 127, 242);
    --color-bgLinePrimarySubtle: rgb(5, 59, 177);
    --color-fgDisabled: rgba(255, 255, 255, 0.451);
    --color-fgInverseDisabled: rgba(0, 0, 0, 0.451);
    --color-fgLink: rgb(140, 139, 243);
    --color-fgLinkHover: rgb(209, 209, 250);
    --color-bgButtonPrimaryHover: rgb(90, 104, 117);
    --color-bgButtonPrimaryActive: rgb(90, 104, 117);
    --color-bgButtonSecondary: rgba(255, 255, 255, 0.122);
    --color-bgButtonSecondaryHover: rgba(255, 255, 255, 0.149);
    --color-bgButtonSecondaryActive: rgba(255, 255, 255, 0.149);
    --color-bgButtonBrand: rgb(217, 225, 7);
    --color-bgButtonInverse: rgb(26, 26, 26);
    --color-bgButtonInverseHover: rgb(38, 38, 38);
    --color-bgButtonInverseActive: rgb(51, 51, 51);
    --color-bgButtonInverseDisabled: rgba(1, 23, 43, 0.102);
    --color-bgButtonDisabled: rgba(255, 255, 255, 0.102);

    --color-transparent: rgba(255, 255, 255, 0);
  }
}

/* --- Colors (dark) — manual override via data-theme="dark" --- */
:root[data-theme='dark'] {
  --color-fg: rgb(255, 255, 255);
  --color-fgMuted: rgba(255, 255, 255, 0.651);
  --color-fgInverse: rgba(0, 0, 0, 0.851);
  --color-fgPrimary: rgb(230, 232, 234);
  --color-fgWarning: rgb(242, 100, 20);
  --color-fgNegative: rgb(251, 153, 153);
  --color-fgPositive: rgb(0, 196, 91);

  --color-bg: rgb(0, 0, 0);
  --color-bgAlternate: rgb(26, 26, 26);
  --color-bgInverse: rgb(255, 255, 255);
  --color-bgOverlay: rgba(0, 0, 0, 0.502);
  --color-bgElevation1: rgb(26, 26, 26);
  --color-bgElevation2: rgb(38, 38, 38);
  --color-bgPrimary: rgb(65, 81, 96);
  --color-bgPrimaryWash: rgb(1, 23, 43);
  --color-bgSecondary: rgb(26, 26, 26);
  --color-bgTertiary: rgb(51, 51, 51);
  --color-bgSecondaryWash: rgb(20, 21, 25);
  --color-bgNegative: rgb(214, 8, 8);
  --color-bgNegativeWash: rgba(247, 50, 50, 0.149);
  --color-bgPositive: rgb(0, 196, 91);
  --color-bgPositiveWash: rgba(0, 231, 107, 0.149);
  --color-bgWarning: rgb(242, 100, 20);
  --color-bgWarningWash: rgba(242, 100, 20, 0.149);

  --color-bgLine: rgba(255, 255, 255, 0.18);
  --color-bgLineHeavy: rgba(138, 145, 158, 0.66);
  --color-bgLineInverse: rgb(0, 0, 0);
  --color-bgLinePrimary: rgb(128, 127, 242);
  --color-bgLinePrimarySubtle: rgb(5, 59, 177);
  --color-fgDisabled: rgba(255, 255, 255, 0.451);
  --color-fgInverseDisabled: rgba(0, 0, 0, 0.451);
  --color-fgLink: rgb(140, 139, 243);
  --color-fgLinkHover: rgb(209, 209, 250);
  --color-bgButtonPrimaryHover: rgb(90, 104, 117);
  --color-bgButtonPrimaryActive: rgb(90, 104, 117);
  --color-bgButtonSecondary: rgba(255, 255, 255, 0.122);
  --color-bgButtonSecondaryHover: rgba(255, 255, 255, 0.149);
  --color-bgButtonSecondaryActive: rgba(255, 255, 255, 0.149);
  --color-bgButtonBrand: rgb(217, 225, 7);
  --color-bgButtonInverse: rgb(26, 26, 26);
  --color-bgButtonInverseHover: rgb(38, 38, 38);
  --color-bgButtonInverseActive: rgb(51, 51, 51);
  --color-bgButtonInverseDisabled: rgba(1, 23, 43, 0.102);
  --color-bgButtonDisabled: rgba(255, 255, 255, 0.102);

  --color-transparent: rgba(255, 255, 255, 0);
}

/* Neon base adapter: shadcn/ui's slots alias Neon roles from theme.css, so
 * light and dark both come from theme.css alone, and theme.css takes each
 * role's color from Core's Theme (theme/css/core-roles.json names the token)
 * and each type role's size and line height from a Core text style
 * (theme/css/core-type-roles.json names it).
 * Imported by src/index.css after Tailwind; theme.css is the canonical CSS
 * adapter, copied as-is. */
@import "./theme.css";

/* Components use Neon roles, never dark: classes; the variant exists only for
 * code that already has them. AppRoot sets data-theme on <html>. */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

@theme inline {
  --font-sans: var(--fontFamily-body);

  /* Every Neon type role is a text-<role> utility with its own line height and
   * weight. lib/utils.ts lists the same roles in cn's font-size group. */
  --text-display1: var(--fontSize-display1); --text-display1--line-height: var(--lineHeight-display1); --text-display1--font-weight: var(--fontWeight-display1);
  --text-display2: var(--fontSize-display2); --text-display2--line-height: var(--lineHeight-display2); --text-display2--font-weight: var(--fontWeight-display2);
  --text-display3: var(--fontSize-display3); --text-display3--line-height: var(--lineHeight-display3); --text-display3--font-weight: var(--fontWeight-display3);
  --text-title1: var(--fontSize-title1); --text-title1--line-height: var(--lineHeight-title1); --text-title1--font-weight: var(--fontWeight-title1);
  --text-title2: var(--fontSize-title2); --text-title2--line-height: var(--lineHeight-title2); --text-title2--font-weight: var(--fontWeight-title2);
  --text-title3: var(--fontSize-title3); --text-title3--line-height: var(--lineHeight-title3); --text-title3--font-weight: var(--fontWeight-title3);
  --text-title4: var(--fontSize-title4); --text-title4--line-height: var(--lineHeight-title4); --text-title4--font-weight: var(--fontWeight-title4);
  --text-headline: var(--fontSize-headline); --text-headline--line-height: var(--lineHeight-headline); --text-headline--font-weight: var(--fontWeight-headline);
  --text-body: var(--fontSize-body); --text-body--line-height: var(--lineHeight-body); --text-body--font-weight: var(--fontWeight-body);
  --text-label1: var(--fontSize-label1); --text-label1--line-height: var(--lineHeight-label1); --text-label1--font-weight: var(--fontWeight-label1);
  --text-label2: var(--fontSize-label2); --text-label2--line-height: var(--lineHeight-label2); --text-label2--font-weight: var(--fontWeight-label2);
  --text-caption: var(--fontSize-caption); --text-caption--line-height: var(--lineHeight-caption); --text-caption--font-weight: var(--fontWeight-caption);
  --text-legal: var(--fontSize-legal); --text-legal--line-height: var(--lineHeight-legal); --text-legal--font-weight: var(--fontWeight-legal);

  --radius-sm: var(--borderRadius-100);
  --radius-md: var(--borderRadius-200);
  --radius-lg: var(--borderRadius-300);
  --radius-xl: var(--borderRadius-400);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  /* Neon roles shadcn has no slot for. */
  --color-positive: var(--color-fgPositive);
  --color-warning: var(--color-fgWarning);
  --color-negative: var(--color-fgNegative);
  --color-line-heavy: var(--color-bgLineHeavy);
  --color-inverse: var(--inverse);
  --color-inverse-foreground: var(--inverse-foreground);
  --color-overlay: var(--color-bgOverlay);
  --color-positive-wash: var(--color-bgPositiveWash);
  --color-warning-wash: var(--color-bgWarningWash);
  --color-negative-wash: var(--color-bgNegativeWash);
  --color-tag-positive: var(--tag-positive);
  --color-tag-warning: var(--tag-warning);
  --color-tag-negative: var(--tag-negative);
  --color-primary-disabled: var(--primary-disabled);
  --color-secondary-disabled: var(--secondary-disabled);
  --color-destructive-disabled: var(--destructive-disabled);
  /* Core's Button and Link tokens, for the button item: each Type's fill at
   * Hover and Active, the Disabled look, and the label inks shadcn has no slot for. */
  --color-primary-hover: var(--primary-hover);
  --color-primary-active: var(--primary-active);
  --color-primary-disabled-foreground: var(--primary-disabled-foreground);
  --color-destructive-hover: var(--color-bgButtonDangerHover);
  --color-destructive-active: var(--color-bgButtonDangerActive);
  --color-button-secondary: var(--button-secondary);
  --color-button-secondary-hover: var(--button-secondary-hover);
  --color-button-secondary-active: var(--button-secondary-active);
  --color-button-brand: var(--color-bgButtonBrand);
  --color-button-brand-hover: var(--color-bgButtonBrandHover);
  --color-button-brand-active: var(--color-bgButtonBrandActive);
  --color-button-brand-foreground: var(--color-fgOnBrand);
  --color-button-inverse: var(--color-bgButtonInverse);
  --color-button-inverse-foreground: var(--color-fg);
  --color-button-inverse-hover: var(--color-bgButtonInverseHover);
  --color-button-inverse-active: var(--color-bgButtonInverseActive);
  --color-button-inverse-disabled: var(--color-bgButtonInverseDisabled);
  --color-button-inverse-disabled-foreground: var(--color-fgInverseDisabled);
  --color-button-disabled: var(--button-disabled);
  --color-button-disabled-foreground: var(--button-disabled-foreground);
  --color-link: var(--link);
  --color-link-hover: var(--link-hover);
  /* Core's button label below Large: Subheadline and Footnote in Medium (500), a weight no type
   * role holds at those sizes. For the button item; lib/utils.ts lists them in cn's font-size group. */
  --text-button-md: var(--fontSize-label1); --text-button-md--line-height: var(--lineHeight-label1); --text-button-md--font-weight: 500;
  --text-button-xs: var(--fontSize-caption); --text-button-xs--line-height: var(--lineHeight-caption); --text-button-xs--font-weight: 500;
}

:root {
  --background: var(--color-bg);
  --foreground: var(--color-fg);
  --card: var(--color-bgElevation1);
  --card-foreground: var(--color-fg);
  /* Core's floating surfaces (Alert, Sheet, Menu, Toggletip) are Layer/layer-01,
   * the card's role; layer-02 is for a container that sits on layer-01. */
  --popover: var(--color-bgElevation1);
  --popover-foreground: var(--color-fg);
  --primary: var(--color-bgPrimary);
  --secondary: var(--color-bgSecondary);
  --secondary-foreground: var(--color-fg);
  --muted: var(--color-bgSecondary);
  --muted-foreground: var(--color-fgMuted);
  --accent: var(--color-bgAlternate);
  --accent-foreground: var(--color-fg);
  /* A Neon slot shadcn lacks: the Tooltip, the checked SegmentedControl item
   * and the pressed Toggle fill in the text color, so the Immersive Themes
   * adapter can remap it as it does the shadcn slots. */
  --inverse: var(--color-bgInverse);
  --inverse-foreground: var(--color-fgInverse);
  --destructive: var(--color-bgNegative);
  --border: var(--color-bgLine);
  /* PROVISIONAL: --input keeps the role CDS defaults use, which has no
   * Core Theme token; the field items take Core's Field and Border tokens when
   * they are retuned (#210). */
  --input: var(--color-bgLineHeavy);
  /* Core's Focus/focus. */
  --ring: var(--color-bgLinePrimary);
  /* Text on filled colors (onColorLabel): fgInverse in light. */
  --primary-foreground: var(--color-fgInverse);
  --destructive-foreground: var(--color-fgInverse);
  /* PROVISIONAL: tag inks. Light tags take the spectrum shades CDS draws
   * tags in (Green/145, Yellow/170, Red/130), 4.8–6.9:1 on the washes, until
   * the tag is retuned to Core's Tag tokens (#210). fgWarning is 3.93:1 on its
   * light wash; fgPositive and fgNegative now pass there (5.54 and 7.97:1). */
  --tag-positive: rgb(0, 127, 59);
  --tag-warning: rgb(87, 90, 3);
  --tag-negative: rgb(200, 8, 8);
  /* The primary Button's states, from Core's Button tokens: its fill at Hover
   * and Active, and Core's Disabled fill and label, which dim by their own
   * alpha and not by opacity. Slots, so an Immersive Theme restates them. */
  --primary-hover: var(--color-bgButtonPrimaryHover);
  --primary-active: var(--color-bgButtonPrimaryActive);
  --primary-disabled: var(--color-bgButtonDisabled);
  --primary-disabled-foreground: var(--color-fgDisabled);
  /* The same for Core's secondary fill (a ghost Button's Hover and Active too),
   * every other Button's Disabled fill and label, and the Link ink. */
  --button-secondary: var(--color-bgButtonSecondary);
  --button-secondary-hover: var(--color-bgButtonSecondaryHover);
  --button-secondary-active: var(--color-bgButtonSecondaryActive);
  --button-disabled: var(--color-bgButtonDisabled);
  --button-disabled-foreground: var(--color-fgDisabled);
  --link: var(--color-fgLink);
  --link-hover: var(--color-fgLinkHover);
  /* Disabled fills (spike trap 4), for the controls not yet retuned to Core:
   * CDS blends a filled control's color into the page background at 75%,
   * raised for colors far from the background in luminance (getBlendedColor).
   * Those controls also fade to 50% opacity, as in CDS. The Button no longer
   * reads them. */
  --secondary-disabled: color-mix(in srgb, var(--secondary) 75%, var(--background));
  --destructive-disabled: color-mix(in srgb, var(--destructive) 92%, var(--background));
  /* CDS Tray is bordered (1px bgLine) in dark only, so a sheet's border
   * width switches with the mode; a width, not light-dark(), which Tailwind's
   * polyfill breaks under AppRoot's inline color-scheme. */
  --sheet-border-width: 0px;
}

/* Text on filled colors in dark: filled buttons take fg (white), Core's
 * Text/text-on-color; white on dark bgNegative is 5.39:1. Matches theme.css's
 * own dark selectors.
 * PROVISIONAL: dark tags take fgPositive, fgWarning and fgNegative, which
 * on their washes over the page are 7.32, 5.77 and 9.10:1, and over a card
 * 5.49, 4.53 and 7.28:1. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --primary-foreground: var(--color-fg);
    --destructive-foreground: var(--color-fg);
    --destructive-disabled: color-mix(in srgb, var(--destructive) 75%, var(--background));
    --tag-positive: var(--color-fgPositive);
    --tag-warning: var(--color-fgWarning);
    --tag-negative: var(--color-fgNegative);
    --sheet-border-width: 1px;
  }
}
:root[data-theme="dark"] {
  --primary-foreground: var(--color-fg);
  --destructive-foreground: var(--color-fg);
  --destructive-disabled: color-mix(in srgb, var(--destructive) 75%, var(--background));
  --tag-positive: var(--color-fgPositive);
  --tag-warning: var(--color-fgWarning);
  --tag-negative: var(--color-fgNegative);
  --sheet-border-width: 1px;
}

@layer base {
  * { @apply border-border outline-ring/50; }
  body { @apply bg-background text-foreground font-sans text-body; }
}
